INSERT INTO "homepage_sections" ("id","type","title","content","image_url","sort_order","is_active","created_at","updated_at") VALUES('sec-hero-banner','hero','Main Hero Showcase','{"slides":[{"badge":"Special Offer • New Season","heading":"Elevate Your Motion with Pure Precision","subheading":"Explore the new Spring Purple Collection. Engineered with micro-knit breathable fabrics and ultra-responsive lightweight foam soles.","primaryButtonText":"Shop Collection","primaryButtonUrl":"/shop","secondaryButtonText":"Explore Categories","secondaryButtonUrl":"#category-cards","imageUrl":"https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?q=80&w=1200&auto=format&fit=crop","imageAlt":"Spring Purple Collection"},{"badge":"Limited Edition Drop","heading":"Carbon Velocity Racing Series","subheading":"Tested by world-class marathoners. Feel 32% enhanced energy return on every stride with carbon-infused composite plates.","primaryButtonText":"Discover Velocity","primaryButtonUrl":"/shop","secondaryButtonText":"View Top Rated","secondaryButtonUrl":"#trending-products","imageUrl":"https://images.unsplash.com/photo-1552346154-21d32810aba3?q=80&w=1200&auto=format&fit=crop","imageAlt":"Carbon Velocity Footwear"},{"badge":"Trending Worldwide","heading":"Uncompromising Everyday Elegance","subheading":"Minimalist luxury athletic wear designed for seamless transition from high-intensity training to urban streetwear.","primaryButtonText":"Explore Now","primaryButtonUrl":"/shop","secondaryButtonText":"About Our Story","secondaryButtonUrl":"/about","imageUrl":"https://images.unsplash.com/photo-1517838277536-f5f99be501cd?q=80&w=1200&auto=format&fit=crop","imageAlt":"Everyday Luxury Athletics"}]}','https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?q=80&w=1200&auto=format&fit=crop',1,1,'2026-09-13 20:01:11','2026-09-13 20:01:11');
