INSERT INTO "homepage_sections" ("id","type","title","content","image_url","sort_order","is_active","created_at","updated_at") VALUES('sec-trust-bar','trust_bar','Store Trust Bar','{"items":[{"icon":"shipping","title":"Free Worldwide Shipping","description":"On all orders over $50 with live tracking"},{"icon":"return","title":"30-Day Return Policy","description":"Hassle-free exchange & money back guarantee"},{"icon":"secure","title":"Secure Payment","description":"256-bit encrypted checkout protection"},{"icon":"support","title":"24/7 Customer Support","description":"Dedicated concierge team ready to help"}]}',NULL,4,1,'2026-09-13 20:01:11','2026-09-13 20:01:11');
INSERT INTO "homepage_sections" ("id","type","title","content","image_url","sort_order","is_active","created_at","updated_at") VALUES('sec-promo-banner','promo_banner','Mid-Season Breakthrough Banner','{"heading":"Accelerate Beyond Limits with Carbon-Plate Tech","subheading":"Experience 32% greater energy return with our award-winning composite foam and zero-friction matrix. Engineered for athletes who push boundaries.","badgeText":"Limited Edition Release","buttonText":"Discover Apex Velocity","buttonUrl":"/product/apex-velocity-runner-x1","bannerStyle":"split"}','https://images.unsplash.com/photo-1552346154-21d32810aba3?q=80&w=1200&auto=format&fit=crop',5,1,'2026-09-13 20:01:11','2026-09-13 20:01:11');
INSERT INTO "homepage_sections" ("id","type","title","content","image_url","sort_order","is_active","created_at","updated_at") VALUES('sec-brand-story','brand_story','The Apex Standard Brand Story','{"heading":"Built at the Intersection of Innovation & Human Potential","subheading":"Our Performance Manifesto","narrativeText":"We engineer apparel and equipment with relentless attention to biomechanics and endurance. Featherlight materials, hyper-durable composites, and uncompromising ergonomics for athletes who refuse to settle. Every product is stress-tested in elite athletic facilities.","statItems":[{"label":"Fast Dispatch","value":"< 24h","desc":"Express delivery dispatch"},{"label":"Energy Return","value":"+32%","desc":"Carbon-matrix tech"},{"label":"Active Athletes","value":"25,000+","desc":"Worldwide community"},{"label":"Customer Rating","value":"99.4%","desc":"Verified athlete satisfaction"}],"ctaText":"Explore The Full Catalog","ctaUrl":"/shop"}','https://images.unsplash.com/photo-1517838277536-f5f99be501cd?q=80&w=1200&auto=format&fit=crop',6,1,'2026-09-13 20:01:11','2026-09-13 20:01:11');
INSERT INTO "homepage_sections" ("id","type","title","content","image_url","sort_order","is_active","created_at","updated_at") VALUES('sec-new-arrivals','new_arrivals','New Arrivals Showcase','{"badge":"New Collection","heading":"New Arrivals Just For You","discountText":"Save up to 40% OFF on first order","subheading":"Experience cutting-edge athletic engineering designed for fluid movement and modern luxury.","buttonText":"Shop Now","buttonUrl":"/shop","imageUrl":"https://images.unsplash.com/photo-1483985988355-763728e1935b?q=80&w=1200&auto=format&fit=crop"}','https://images.unsplash.com/photo-1483985988355-763728e1935b?q=80&w=1200&auto=format&fit=crop',7,1,'2026-09-13 20:01:11','2026-09-13 20:01:11');
