INSERT INTO "products" ("id","name","slug","description","short_description","sku","price","sale_price","cost_price","stock_quantity","stock_status","low_stock_threshold","track_inventory","allow_backorders","category_id","brand","tags","status","created_at","updated_at","compare_at_price","seo_title","seo_description") VALUES('prod-apex-vrx1','Apex Velocity Runner X1','apex-velocity-runner-x1','Engineered for long-distance marathon dominance. The Apex Velocity Runner X1 features an aerospace-grade carbon fiber propulsion plate sandwiched between twin layers of ultra-light supercritical foam, delivering an unrivaled 32% energy return on every strike.','Marathon-tested road racer with full-length carbon composite plate and responsive foam.','APX-VRX1-BLK',160,139.99,65,42,'in_stock',5,1,0,'cat-footwear','Apex Athletic','["shoes", "running", "marathon", "carbon", "bestseller"]','published','2026-09-13 20:01:11','2026-09-16T01:52:33.353Z',160,'Apex Velocity Runner X1 | High Performance Road Shoe','Experience superior energy return with the Apex Velocity Runner X1 marathon shoe.');
INSERT INTO "products" ("id","name","slug","description","short_description","sku","price","sale_price","cost_price","stock_quantity","stock_status","low_stock_threshold","track_inventory","allow_backorders","category_id","brand","tags","status","created_at","updated_at","compare_at_price","seo_title","seo_description") VALUES('prod-pulse-enduro','Pulse Enduro Carbon Pro','pulse-enduro-carbon-pro','Tackle steep technical climbs and slick descents with unwavering stability. The Pulse Enduro Carbon Pro integrates targeted arch support, breathable water-shedding mesh, and dual-density cushioning.','All-terrain trail runner built with reinforced Kevlar mesh and ultra-grip Vibram lugs.','PLS-END-PRO',185,155,78,28,'in_stock',5,1,0,'cat-footwear','Pulse Pro','["shoes", "trail", "endurance", "grip"]','published','2026-09-13 20:01:11','2026-09-16T01:52:33.353Z',185,'Pulse Enduro Carbon Pro | Trail Endurance Running Shoe','All-weather trail grip and carbon support with Pulse Enduro Pro.');
INSERT INTO "products" ("id","name","slug","description","short_description","sku","price","sale_price","cost_price","stock_quantity","stock_status","low_stock_threshold","track_inventory","allow_backorders","category_id","brand","tags","status","created_at","updated_at","compare_at_price","seo_title","seo_description") VALUES('prod-aero-knit-tee','Aero-Knit Seamless Compression Tee','aero-knit-seamless-compression-tee','Designed to feel like a second skin. The Aero-Knit Seamless Compression Tee utilizes body-mapped ventilation to release heat where athletes sweat most, minimizing friction through flatlock bonded seams.','Ergonomic compression training shirt with graduated ventilation zones and anti-odor silver ion.','AER-KNT-TEE',58,45,18,59,'in_stock',8,1,0,'cat-apparel','Aero Velocity','["apparel", "compression", "training", "seamless", "new"]','published','2026-09-13 20:01:11','2026-09-15T12:40:23.221Z',58,'Aero-Knit Seamless Compression Tee | Apex Apparel','Stay cool and supported with our premier seamless compression training shirt.');
INSERT INTO "products" ("id","name","slug","description","short_description","sku","price","sale_price","cost_price","stock_quantity","stock_status","low_stock_threshold","track_inventory","allow_backorders","category_id","brand","tags","status","created_at","updated_at","compare_at_price","seo_title","seo_description") VALUES('prod-vapor-jacket','Vapor-Shield Weatherproof Windbreaker','vapor-shield-weatherproof-windbreaker','Weighing under 180 grams, the Vapor-Shield Windbreaker provides impervious barrier protection against gusting winds and driving rain without sacrificing breathability during threshold efforts.','Ultra-light 2.5-layer storm shell with DWR finish, packable into its own chest pocket.','VPR-SHD-JKT',140,119,52,24,'in_stock',4,1,0,'cat-apparel','Vanguard Sport','["apparel", "jacket", "windbreaker", "weatherproof"]','published','2026-09-13 20:01:11','2026-09-15T12:40:23.221Z',140,'Vapor-Shield Weatherproof Windbreaker | Vanguard Sport','Packable, lightweight storm jacket engineered for outdoor runners.');
INSERT INTO "products" ("id","name","slug","description","short_description","sku","price","sale_price","cost_price","stock_quantity","stock_status","low_stock_threshold","track_inventory","allow_backorders","category_id","brand","tags","status","created_at","updated_at","compare_at_price","seo_title","seo_description") VALUES('prod-titan-kettlebell','Titan-Grip Precision Competition Kettlebell','titan-grip-precision-competition-kettlebell','Crafted to international competition specifications. Features a bare steel handle with fine texture for superior chalk retention and zero blistering over high-rep snatches.','Uniform dimension cast steel kettlebell with color-coded handle and balanced mass center.','TTN-KB-24KG',85,72,35,34,'in_stock',5,1,0,'cat-equipment','Apex Athletics','["equipment", "kettlebell", "strength", "competition"]','published','2026-09-13 20:01:11','2026-09-15T12:40:23.221Z',85,'Titan-Grip Precision Competition Kettlebell','Flawlessly balanced competition kettlebell for explosive strength workouts.');
INSERT INTO "products" ("id","name","slug","description","short_description","sku","price","sale_price","cost_price","stock_quantity","stock_status","low_stock_threshold","track_inventory","allow_backorders","category_id","brand","tags","status","created_at","updated_at","compare_at_price","seo_title","seo_description") VALUES('prod-velocity-barbell','Kinetic Olympic Training Barbell 20kg','kinetic-olympic-training-barbell-20kg','Engineered for weightlifters who demand consistent whip and smooth sleeve rotation under maximum loads. Hard chrome finish protects against corrosion in high-humidity training gyms.','215,000 PSI tensile strength steel bar with precision needle bearings and dual knurl marks.','KNT-OLY-20KG',295,NULL,120,16,'in_stock',3,1,0,'cat-equipment','Kinetics Lab','["equipment", "barbell", "olympic", "powerlifting"]','published','2026-09-13 20:01:11','2026-09-16T02:11:13.060Z',295,'Kinetic Olympic Training Barbell 20kg | Kinetics Lab','Competition-grade Olympic barbell built for power cleans and heavy deadlifts.');
INSERT INTO "products" ("id","name","slug","description","short_description","sku","price","sale_price","cost_price","stock_quantity","stock_status","low_stock_threshold","track_inventory","allow_backorders","category_id","brand","tags","status","created_at","updated_at","compare_at_price","seo_title","seo_description") VALUES('prod-cryo-gun','Cryo-Pulse Percussion Recovery Gun','cryo-pulse-percussion-recovery-gun','Target deep myofascial tension with rapid percussion. Features 5 speed settings ranging from 1,400 to 3,200 RPM and a rechargeable lithium-ion battery providing up to 6 hours of continuous operation.','Quiet-glide brushless motor delivering 14mm amplitude with hot and cold attachment heads.','CRY-PLS-GUN',220,189,85,35,'in_stock',6,1,0,'cat-recovery','Pulse Pro','["recovery", "massage", "percussion", "tech", "bestseller"]','published','2026-09-13 20:01:11','2026-09-17T20:38:32.655Z',220,'Cryo-Pulse Percussion Recovery Gun | Deep Tissue Recovery','Relieve soreness and accelerate tissue repair with thermal percussive therapy.');
INSERT INTO "products" ("id","name","slug","description","short_description","sku","price","sale_price","cost_price","stock_quantity","stock_status","low_stock_threshold","track_inventory","allow_backorders","category_id","brand","tags","status","created_at","updated_at","compare_at_price","seo_title","seo_description") VALUES('prod-compression-boots','Hydro-Flex Compression Recovery Boots','hydro-flex-compression-recovery-boots','Flushes metabolic waste and revitalizes heavy legs after grueling mileage. Fully customizable pressure zones up to 240 mmHg with calibrated gradient inflation cycles.','Dynamic pneumatic leg compression system with 6 overlapping chambers and digital pressure presets.','HDR-FLX-BTS',340,299,140,9,'in_stock',3,1,0,'cat-recovery','Chronicle Elite','["recovery", "boots", "compression", "circulation"]','published','2026-09-13 20:01:11','2026-09-18T20:20:51.281Z',340,'Hydro-Flex Compression Recovery Boots | Chronicle Elite','Clinical pneumatic recovery boots for rapid post-run rejuvenation.');
INSERT INTO "products" ("id","name","slug","description","short_description","sku","price","sale_price","cost_price","stock_quantity","stock_status","low_stock_threshold","track_inventory","allow_backorders","category_id","brand","tags","status","created_at","updated_at","compare_at_price","seo_title","seo_description") VALUES('prod-aero-pack','AeroSpeed Ultralight Hydration Pack 5L','aerospeed-ultralight-hydration-pack-5l','Designed for ultra-marathoners requiring streamlined access to fuel, hydration, and layers. Features breathable mesh backing and pole-attachment shock cords.','Form-fitting ergonomic vest with dual 500ml soft flasks and zero-bounce chest harness.','AER-SPD-PCK',78,64,26,46,'in_stock',8,1,0,'cat-accessories','Vanguard Sport','["accessories", "hydration", "vest", "running"]','published','2026-09-13 20:01:11','2026-09-17T08:09:24.604Z',78,'AeroSpeed Ultralight Hydration Pack 5L | Vanguard','Zero-bounce lightweight hydration vest for ultra-distance athletes.');
INSERT INTO "products" ("id","name","slug","description","short_description","sku","price","sale_price","cost_price","stock_quantity","stock_status","low_stock_threshold","track_inventory","allow_backorders","category_id","brand","tags","status","created_at","updated_at","compare_at_price","seo_title","seo_description") VALUES('prod-thermal-bottle','Quantum-Flow Insulated Thermal Bottle 750ml','quantum-flow-insulated-thermal-bottle-750ml','Keeps electrolyte drinks ice cold for up to 36 hours. Constructed with 18/8 food-grade pro steel that leaves zero metallic aftertaste and resists heavy denting.','Triple-wall vacuum insulated stainless bottle with high-flow magnetic spout cap.','QNT-FLW-BTL',42,34,12,74,'in_stock',10,1,0,'cat-accessories','Apex Athletic','["accessories", "bottle", "hydration", "thermal"]','published','2026-09-13 20:01:11','2026-09-15T12:40:23.221Z',42,'Quantum-Flow Insulated Thermal Bottle 750ml','High-flow insulated sports hydration bottle for training sessions.');
