PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `categories` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`slug` text NOT NULL,
	`description` text,
	`parent_id` text,
	`image_url` text,
	`sort_order` integer DEFAULT 0 NOT NULL,
	`status` text DEFAULT 'active' NOT NULL,
	`seo_title` text,
	`seo_description` text,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	`updated_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL
);
CREATE TABLE `homepage_sections` (
	`id` text PRIMARY KEY NOT NULL,
	`type` text NOT NULL,
	`title` text NOT NULL,
	`content` text,
	`image_url` text,
	`sort_order` integer DEFAULT 0 NOT NULL,
	`is_active` integer DEFAULT true NOT NULL,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	`updated_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL
);
CREATE TABLE `media` (
	`id` text PRIMARY KEY NOT NULL,
	`url` text NOT NULL,
	`type` text NOT NULL,
	`alt_text` text,
	`size` integer NOT NULL,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL
);
CREATE TABLE `product_images` (
	`id` text PRIMARY KEY NOT NULL,
	`product_id` text NOT NULL,
	`image_url` text NOT NULL,
	`alt_text` text,
	`sort_order` integer DEFAULT 0 NOT NULL,
	`is_main` integer DEFAULT false NOT NULL,
	FOREIGN KEY (`product_id`) REFERENCES `products`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `product_variants` (
	`id` text PRIMARY KEY NOT NULL,
	`product_id` text NOT NULL,
	`sku` text,
	`price` real NOT NULL,
	`sale_price` real,
	`stock` integer DEFAULT 0 NOT NULL,
	`image_url` text,
	`options` text,
	`weight` real,
	`dimensions` text,
	`is_default` integer DEFAULT false NOT NULL,
	FOREIGN KEY (`product_id`) REFERENCES `products`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `products` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`slug` text NOT NULL,
	`description` text,
	`short_description` text,
	`sku` text,
	`price` real NOT NULL,
	`sale_price` real,
	`cost_price` real,
	`stock_quantity` integer DEFAULT 0 NOT NULL,
	`stock_status` text DEFAULT 'in_stock' NOT NULL,
	`low_stock_threshold` integer DEFAULT 5 NOT NULL,
	`track_inventory` integer DEFAULT true NOT NULL,
	`allow_backorders` integer DEFAULT false NOT NULL,
	`category_id` text,
	`brand` text,
	`tags` text,
	`status` text DEFAULT 'draft' NOT NULL,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	`updated_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL, `compare_at_price` real, `seo_title` text, `seo_description` text,
	FOREIGN KEY (`category_id`) REFERENCES `categories`(`id`) ON UPDATE no action ON DELETE set null
);
CREATE TABLE `settings` (
	`id` text PRIMARY KEY NOT NULL,
	`key` text NOT NULL,
	`value` text,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	`updated_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL
);
CREATE TABLE `login_attempts` (
	`id` text PRIMARY KEY NOT NULL,
	`email` text NOT NULL,
	`attempted_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	`success` integer NOT NULL,
	`ip` text
);
CREATE TABLE `sessions` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`token` text NOT NULL,
	`expires_at` text NOT NULL,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `users` (
	`id` text PRIMARY KEY NOT NULL,
	`email` text NOT NULL,
	`password_hash` text NOT NULL,
	`role` text DEFAULT 'admin' NOT NULL,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL
);
CREATE TABLE `attributes` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`slug` text NOT NULL,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL
);
CREATE TABLE `attribute_values` (
	`id` text PRIMARY KEY NOT NULL,
	`attribute_id` text NOT NULL,
	`value` text NOT NULL,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	FOREIGN KEY (`attribute_id`) REFERENCES `attributes`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `carts` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`session_id` text,
	`status` text DEFAULT 'active' NOT NULL,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	`updated_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null
);
CREATE TABLE `cart_items` (
	`id` text PRIMARY KEY NOT NULL,
	`cart_id` text NOT NULL,
	`product_id` text NOT NULL,
	`variant_id` text,
	`quantity` integer DEFAULT 1 NOT NULL,
	`unit_price` real NOT NULL,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	`updated_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	FOREIGN KEY (`cart_id`) REFERENCES `carts`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`product_id`) REFERENCES `products`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`variant_id`) REFERENCES `product_variants`(`id`) ON UPDATE no action ON DELETE set null
);
CREATE TABLE `orders` (
  `id` text PRIMARY KEY NOT NULL,
  `customer_name` text NOT NULL,
  `phone` text NOT NULL,
  `email` text,
  `address` text NOT NULL,
  `city` text NOT NULL,
  `notes` text,
  `subtotal` real NOT NULL,
  `shipping` real NOT NULL,
  `total` real NOT NULL,
  `payment_method` text DEFAULT 'cod' NOT NULL,
  `status` text DEFAULT 'pending' NOT NULL,
  `created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
  `updated_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL
, discount_amount REAL DEFAULT 0, discount_code TEXT, discount_type TEXT, has_review INTEGER DEFAULT 0, customer_id TEXT, courier_name TEXT, tracking_number TEXT, estimated_delivery TEXT, status_notes TEXT, country TEXT, state TEXT, tax_amount REAL DEFAULT 0, tax_rate REAL DEFAULT 0, tax_label TEXT, shipping_zone_id TEXT);
CREATE TABLE `order_items` (
  `id` text PRIMARY KEY NOT NULL,
  `order_id` text NOT NULL,
  `product_id` text NOT NULL,
  `variant_id` text,
  `product_name` text NOT NULL,
  `variant_name` text,
  `quantity` integer NOT NULL,
  `unit_price` real NOT NULL,
  `line_total` real NOT NULL,
  `created_at` text DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
  FOREIGN KEY (`order_id`) REFERENCES `orders`(`id`) ON UPDATE no action ON DELETE cascade,
  FOREIGN KEY (`product_id`) REFERENCES `products`(`id`) ON UPDATE no action ON DELETE no action,
  FOREIGN KEY (`variant_id`) REFERENCES `product_variants`(`id`) ON UPDATE no action ON DELETE set null
);
CREATE TABLE coupons (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  code TEXT UNIQUE NOT NULL,
  description TEXT,
  type TEXT NOT NULL,
  value REAL NOT NULL,
  min_order_value REAL,
  max_discount REAL,
  apply_to TEXT DEFAULT 'all',
  apply_to_id TEXT,
  buy_quantity INTEGER,
  get_quantity INTEGER,
  usage_limit INTEGER,
  used_count INTEGER DEFAULT 0,
  per_customer_limit INTEGER DEFAULT 1,
  start_date TEXT,
  end_date TEXT,
  first_order_only INTEGER DEFAULT 0,
  is_visible INTEGER DEFAULT 1,
  is_auto_apply INTEGER DEFAULT 0,
  is_featured INTEGER DEFAULT 0,
  is_active INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (CURRENT_TIMESTAMP),
  updated_at TEXT DEFAULT (CURRENT_TIMESTAMP)
);
CREATE TABLE coupon_usages (
  id TEXT PRIMARY KEY,
  coupon_id TEXT NOT NULL,
  order_id TEXT NOT NULL,
  customer_email TEXT,
  customer_id TEXT,
  discount_amount REAL NOT NULL,
  used_at TEXT NOT NULL
);
CREATE TABLE pages (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  slug TEXT NOT NULL,
  title TEXT NOT NULL,
  content TEXT, -- HTML or JSON
  seo_title TEXT,
  seo_description TEXT,
  og_image TEXT,
  show_in_footer INTEGER DEFAULT 0,
  is_published INTEGER DEFAULT 1,
  is_default INTEGER DEFAULT 0, -- true for About, Privacy, etc.
  sort_order INTEGER DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  UNIQUE(slug)
);
CREATE TABLE faqs (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  question TEXT NOT NULL,
  answer TEXT NOT NULL,
  category TEXT,
  sort_order INTEGER DEFAULT 0,
  is_active INTEGER DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);
CREATE TABLE contact_messages (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  subject TEXT,
  message TEXT NOT NULL,
  is_read INTEGER DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);
CREATE TABLE reviews (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  product_id TEXT NOT NULL,
  order_id TEXT,
  customer_id TEXT,
  customer_name TEXT NOT NULL,
  customer_email TEXT NOT NULL,
  rating INTEGER NOT NULL CHECK(rating >= 1 AND rating <= 5),
  title TEXT,
  content TEXT NOT NULL,
  is_verified_purchase INTEGER DEFAULT 0,
  status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'rejected')),
  helpful_count INTEGER DEFAULT 0,
  not_helpful_count INTEGER DEFAULT 0,
  admin_reply TEXT,
  admin_reply_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE review_images (
  id TEXT PRIMARY KEY,
  review_id TEXT NOT NULL,
  image_url TEXT NOT NULL,
  sort_order INTEGER DEFAULT 0,
  created_at TEXT NOT NULL,
  FOREIGN KEY (review_id) REFERENCES reviews(id) ON DELETE CASCADE
);
CREATE TABLE review_helpful (
  id TEXT PRIMARY KEY,
  review_id TEXT NOT NULL,
  user_ip TEXT NOT NULL,
  vote_type TEXT NOT NULL CHECK(vote_type IN ('helpful', 'not_helpful')),
  created_at TEXT NOT NULL,
  UNIQUE(review_id, user_ip),
  FOREIGN KEY (review_id) REFERENCES reviews(id) ON DELETE CASCADE
);
CREATE TABLE customers (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  email TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  name TEXT NOT NULL,
  phone TEXT,
  status TEXT DEFAULT 'active' CHECK(status IN ('active', 'suspended')),
  is_verified INTEGER DEFAULT 0,
  last_login TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE customer_sessions (
  id TEXT PRIMARY KEY,
  customer_id TEXT NOT NULL,
  token TEXT UNIQUE NOT NULL,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE
);
CREATE TABLE customer_addresses (
  id TEXT PRIMARY KEY,
  customer_id TEXT NOT NULL,
  label TEXT DEFAULT 'Home',
  full_name TEXT NOT NULL,
  phone TEXT NOT NULL,
  address TEXT NOT NULL,
  city TEXT NOT NULL,
  country TEXT DEFAULT 'Pakistan',
  postal_code TEXT,
  is_default INTEGER DEFAULT 0,
  created_at TEXT NOT NULL,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE
);
CREATE TABLE notifications (
  id TEXT PRIMARY KEY,
  customer_id TEXT NOT NULL,
  type TEXT NOT NULL, -- 'order_status', 'review_approved', 'coupon', 'welcome', 'promotion', 'stock_back', 'custom'
  title TEXT NOT NULL,
  message TEXT NOT NULL,
  link TEXT,
  is_read INTEGER DEFAULT 0,
  created_at TEXT NOT NULL,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE
);
CREATE TABLE customer_wishlist (
  id TEXT PRIMARY KEY,
  customer_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE(customer_id, product_id),
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE
);
CREATE TABLE broadcasts (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  title TEXT NOT NULL,
  message TEXT NOT NULL,
  image_url TEXT,
  link_url TEXT,
  button_text TEXT,
  type TEXT DEFAULT 'info', -- 'info', 'promotion', 'announcement', 'warning'
  target TEXT DEFAULT 'all', -- 'all', 'registered', 'guest'
  status TEXT DEFAULT 'sent', -- 'sent', 'draft', 'scheduled', 'archived'
  sent_at TEXT,
  scheduled_for TEXT,
  created_at TEXT NOT NULL,
  created_by TEXT
);
CREATE TABLE broadcast_views (
  id TEXT PRIMARY KEY,
  broadcast_id TEXT NOT NULL,
  customer_id TEXT,
  visitor_id TEXT,
  is_dismissed INTEGER DEFAULT 0,
  viewed_at TEXT NOT NULL,
  clicked_at TEXT,
  FOREIGN KEY (broadcast_id) REFERENCES broadcasts(id) ON DELETE CASCADE,
  UNIQUE(broadcast_id, visitor_id)
);
CREATE TABLE tax_rates (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  country TEXT NOT NULL,
  state TEXT,
  city TEXT,
  rate REAL NOT NULL,
  label TEXT,
  tax_type TEXT DEFAULT 'exclusive',
  is_active INTEGER DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(country, state, city)
);
CREATE TABLE tax_settings (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  is_enabled INTEGER DEFAULT 1,
  default_rate REAL DEFAULT 0,
  default_label TEXT DEFAULT 'Tax',
  default_tax_type TEXT DEFAULT 'exclusive',
  apply_to_shipping INTEGER DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE shipping_zones (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  name TEXT NOT NULL,
  countries TEXT NOT NULL,
  states TEXT,
  rate_type TEXT DEFAULT 'flat',
  rate REAL DEFAULT 0,
  free_shipping_threshold REAL,
  min_order_value REAL,
  delivery_time_min INTEGER,
  delivery_time_max INTEGER,
  is_active INTEGER DEFAULT 1,
  sort_order INTEGER DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE product_bundles (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  name TEXT NOT NULL,
  slug TEXT UNIQUE NOT NULL,
  description TEXT,
  bundle_price REAL NOT NULL,
  original_price REAL NOT NULL,
  discount_percentage REAL,
  image_url TEXT,
  status TEXT DEFAULT 'active',
  is_featured INTEGER DEFAULT 0,
  sort_order INTEGER DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE bundle_items (
  id TEXT PRIMARY KEY,
  bundle_id TEXT NOT NULL,
  product_id TEXT NOT NULL,
  variant_id TEXT,
  quantity INTEGER DEFAULT 1,
  sort_order INTEGER DEFAULT 0,
  FOREIGN KEY (bundle_id) REFERENCES product_bundles(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
);
CREATE TABLE trust_badges (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  icon TEXT NOT NULL,              -- Lucide icon name (e.g., 'shield-check', 'truck', 'refresh-cw')
  title TEXT NOT NULL,              -- e.g., "Secure Checkout"
  description TEXT,                 -- e.g., "256-bit SSL Encryption"
  location TEXT DEFAULT 'all',     -- 'all', 'product', 'cart', 'checkout', 'footer'
  sort_order INTEGER DEFAULT 0,
  is_active INTEGER DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE payment_icons (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  name TEXT NOT NULL,              -- e.g., "Visa", "Mastercard"
  icon_svg TEXT,                    -- SVG or icon identifier
  sort_order INTEGER DEFAULT 0,
  is_active INTEGER DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE cookie_consent_settings (
  id TEXT PRIMARY KEY,
  tenant_id TEXT,
  is_enabled INTEGER DEFAULT 1,
  banner_title TEXT DEFAULT 'We use cookies',
  banner_message TEXT DEFAULT 'We use cookies to improve your experience, analyze traffic, and personalize content.',
  accept_text TEXT DEFAULT 'Accept All',
  reject_text TEXT DEFAULT 'Reject All',
  customize_text TEXT DEFAULT 'Customize',
  position TEXT DEFAULT 'bottom',  -- 'bottom', 'top'
  theme TEXT DEFAULT 'light',       -- 'light', 'dark'
  analytics_enabled INTEGER DEFAULT 1,
  marketing_enabled INTEGER DEFAULT 1,
  functional_enabled INTEGER DEFAULT 1,
  cookie_policy_content TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE installed_apps (
  id TEXT PRIMARY KEY,
  version TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1,
  installed_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  settings TEXT,
  permissions TEXT,
  installed_by TEXT
);
CREATE TABLE app_install_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  app_id TEXT NOT NULL,
  action TEXT NOT NULL,
  performed_at INTEGER NOT NULL,
  performed_by TEXT,
  notes TEXT
);
CREATE TABLE IF NOT EXISTS "app_hello-world_test" (id TEXT PRIMARY KEY, test_val TEXT);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX `categories_slug_unique` ON `categories` (`slug`);
CREATE UNIQUE INDEX `product_variants_sku_unique` ON `product_variants` (`sku`);
CREATE UNIQUE INDEX `products_slug_unique` ON `products` (`slug`);
CREATE UNIQUE INDEX `products_sku_unique` ON `products` (`sku`);
CREATE UNIQUE INDEX `settings_key_unique` ON `settings` (`key`);
CREATE UNIQUE INDEX `sessions_token_unique` ON `sessions` (`token`);
CREATE UNIQUE INDEX `users_email_unique` ON `users` (`email`);
CREATE UNIQUE INDEX `attributes_slug_unique` ON `attributes` (`slug`);
CREATE INDEX `idx_carts_session_id` ON `carts` (`session_id`);
CREATE INDEX `idx_carts_user_id` ON `carts` (`user_id`);
CREATE INDEX `idx_cart_items_cart_id` ON `cart_items` (`cart_id`);
CREATE INDEX `idx_cart_items_product_id` ON `cart_items` (`product_id`);
CREATE INDEX `idx_orders_status` ON `orders`(`status`);
CREATE INDEX `idx_orders_created_at` ON `orders`(`created_at`);
CREATE INDEX `idx_order_items_order_id` ON `order_items`(`order_id`);
CREATE INDEX idx_products_category_id ON products(category_id);
CREATE INDEX idx_products_status ON products(status);
CREATE INDEX idx_product_images_product_id ON product_images(product_id);
CREATE INDEX idx_product_variants_product_id ON product_variants(product_id);
CREATE INDEX idx_categories_parent_id ON categories(parent_id);
CREATE INDEX idx_media_created_at ON media(created_at);
CREATE INDEX idx_homepage_sections_sort_order ON homepage_sections(sort_order);
CREATE INDEX idx_homepage_sections_is_active ON homepage_sections(is_active);
CREATE INDEX idx_products_status_cat_created ON products(status, category_id, created_at);
CREATE INDEX idx_products_status_created ON products(status, created_at);
CREATE INDEX idx_orders_status_created ON orders(status, created_at);
CREATE INDEX idx_cart_items_cart_prod ON cart_items(cart_id, product_id);
CREATE INDEX idx_orders_customer_email ON orders(email);
CREATE INDEX idx_orders_customer_phone ON orders(phone);
CREATE INDEX idx_order_items_product_id ON order_items(product_id);
CREATE INDEX idx_coupons_code ON coupons(code);
CREATE INDEX idx_coupons_active ON coupons(is_active);
CREATE INDEX idx_coupon_usages_coupon_id ON coupon_usages(coupon_id);
CREATE INDEX idx_coupon_usages_order_id ON coupon_usages(order_id);
CREATE INDEX idx_pages_slug ON pages(slug);
CREATE INDEX idx_pages_published ON pages(is_published);
CREATE INDEX idx_faqs_active ON faqs(is_active);
CREATE INDEX idx_faqs_sort ON faqs(sort_order);
CREATE INDEX idx_contact_read ON contact_messages(is_read);
CREATE INDEX idx_reviews_product_id ON reviews(product_id);
CREATE INDEX idx_reviews_status ON reviews(status);
CREATE INDEX idx_reviews_rating ON reviews(rating);
CREATE INDEX idx_reviews_created ON reviews(created_at);
CREATE INDEX idx_review_images_review_id ON review_images(review_id);
CREATE INDEX idx_review_helpful_review_id ON review_helpful(review_id);
CREATE INDEX idx_customers_email ON customers(email);
CREATE INDEX idx_customer_sessions_token ON customer_sessions(token);
CREATE INDEX idx_customer_sessions_customer_id ON customer_sessions(customer_id);
CREATE INDEX idx_customer_addresses_customer_id ON customer_addresses(customer_id);
CREATE INDEX idx_notifications_customer_id ON notifications(customer_id);
CREATE INDEX idx_notifications_is_read ON notifications(is_read);
CREATE INDEX idx_orders_customer_id ON orders(customer_id);
CREATE INDEX idx_customer_wishlist_customer_id ON customer_wishlist(customer_id);
CREATE INDEX idx_broadcasts_status ON broadcasts(status);
CREATE INDEX idx_broadcasts_target ON broadcasts(target);
CREATE INDEX idx_broadcasts_created_at ON broadcasts(created_at);
CREATE INDEX idx_broadcast_views_broadcast_id ON broadcast_views(broadcast_id);
CREATE INDEX idx_broadcast_views_visitor_id ON broadcast_views(visitor_id);
CREATE INDEX idx_broadcast_views_is_dismissed ON broadcast_views(is_dismissed);
CREATE INDEX idx_orders_tracking_number ON orders(tracking_number);
CREATE INDEX idx_tax_rates_country ON tax_rates(country);
CREATE INDEX idx_tax_rates_country_state ON tax_rates(country, state);
CREATE INDEX idx_shipping_zones_active ON shipping_zones(is_active);
CREATE INDEX idx_shipping_zones_sort ON shipping_zones(sort_order);
CREATE INDEX idx_bundles_status ON product_bundles(status);
CREATE INDEX idx_bundles_slug ON product_bundles(slug);
CREATE INDEX idx_bundles_featured ON product_bundles(is_featured);
CREATE INDEX idx_bundle_items_bundle ON bundle_items(bundle_id);
CREATE INDEX idx_bundle_items_product ON bundle_items(product_id);
CREATE INDEX idx_trust_badges_active ON trust_badges(is_active);
CREATE INDEX idx_trust_badges_location ON trust_badges(location);
CREATE INDEX idx_payment_icons_active ON payment_icons(is_active);
CREATE INDEX idx_installed_apps_enabled ON installed_apps(enabled);
CREATE INDEX idx_app_install_log_app_id ON app_install_log(app_id);
CREATE INDEX idx_sessions_token ON sessions(token);
CREATE INDEX idx_sessions_expires_at ON sessions(expires_at);
CREATE INDEX idx_login_attempts_email ON login_attempts(email);
CREATE INDEX idx_login_attempts_attempted_at ON login_attempts(attempted_at);
